def combine(a,u,b,v):
    if len(u)!=2 or len(v)!=2:raise ValueError("Vetores 2D necessários")
    return tuple(a*x+b*y for x,y in zip(u,v))
assert combine(1,(1,0),2,(1,1))==(3,2)
try:combine(1,(1,0,2),2,(1,1))
except ValueError:pass
else:raise AssertionError("Dimensão incompatível aceita")
